DECLARE
  v_user_id    UUID := auth.uid();
  v_gym_id     UUID;
  v_code       TEXT;
BEGIN
  -- 1. Verificar autenticación
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;

  -- 2. Verificar que el usuario no tenga ya un gym asignado
  IF EXISTS (
    SELECT 1 FROM gym.usuarios
     WHERE id_usuario = v_user_id AND id_gimnasio IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'El usuario ya tiene un gimnasio registrado';
  END IF;

  -- 3. Crear el gimnasio
  INSERT INTO gym.gimnasios (
    nombre, ruc, ciudad, pais, direccion, telefono, email,
    plan_suscripcion, estado
  )
  VALUES (
    p_nombre, p_ruc, p_ciudad, p_pais, p_direccion,
    p_telefono, p_email, p_plan, 'activo'
  )
  RETURNING id_gimnasio INTO v_gym_id;

  -- 4. Generar y registrar código de acceso
  v_code := public.generate_gym_code(p_nombre);
  INSERT INTO gym.codigos_acceso (id_gimnasio, codigo, tipo, descripcion, creado_por)
  VALUES (v_gym_id, v_code, 'general', 'Código principal', v_user_id);

  -- 5. Actualizar perfil del usuario → asignarlo como gerente del gym
  UPDATE gym.usuarios
     SET id_gimnasio = v_gym_id,
         rol         = 'gerente',
         cargo       = COALESCE(cargo, p_cargo),
         estado      = 'activo'
   WHERE id_usuario = v_user_id;

  -- Si el usuario aún no tiene fila en gym.usuarios, crearla
  IF NOT FOUND THEN
    INSERT INTO gym.usuarios (id_usuario, email, nombre, cargo, id_gimnasio, rol, estado)
    SELECT
      v_user_id,
      au.email,
      COALESCE(NULLIF(au.raw_user_meta_data->>'nombre', ''), split_part(au.email, '@', 1)),
      p_cargo,
      v_gym_id,
      'gerente',
      'activo'
    FROM auth.users au WHERE au.id = v_user_id
    ON CONFLICT (id_usuario) DO UPDATE
      SET id_gimnasio = v_gym_id, rol = 'gerente', cargo = p_cargo;
  END IF;

  RETURN jsonb_build_object(
    'ok',          true,
    'id_gimnasio', v_gym_id,
    'codigo',      v_code,
    'plan',        p_plan
  );

EXCEPTION WHEN OTHERS THEN
  RAISE EXCEPTION 'bootstrap_gym_tenant: % (%)', SQLERRM, SQLSTATE;
END;

DECLARE
  v_uid UUID := auth.uid();
  v_row public.profiles%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('found', false, 'reason', 'not_authenticated');
  END IF;

  SELECT * INTO v_row FROM public.profiles WHERE id = v_uid;

  IF v_row.id IS NULL THEN
    RETURN jsonb_build_object('found', false, 'reason', 'no_profile');
  END IF;

  RETURN jsonb_build_object(
    'found',            true,
    'id',               v_row.id,
    'full_name',        v_row.full_name,
    'avatar_url',       v_row.avatar_url,
    'genero',           v_row.genero,
    'numero_documento', v_row.numero_documento,
    'tenant_id',        v_row.tenant_id
  );
END;

DECLARE
  v_row rrhh.codigos_registro_voluntario;
  v_code text;
BEGIN
  IF NOT public.fn_has_permission('volunteers.invite') AND NOT public.fn_is_tenant_admin() THEN
    RAISE EXCEPTION 'No autorizado';
  END IF;

  v_code := upper(substr(encode(gen_random_bytes(8), 'hex'), 1, 12));

  INSERT INTO rrhh.codigos_registro_voluntario(
    tenant_id, codigo, email_objetivo, numero_documento_objetivo, nombres_objetivo,
    apellidos_objetivo, id_solicitud, expires_at, created_by, updated_by
  )
  VALUES (
    public.fn_current_tenant_id(), v_code, p_email, p_numero_documento, p_nombres,
    p_apellidos, p_id_solicitud, now() + make_interval(mins => p_expires_in_minutes),
    auth.uid(), auth.uid()
  )
  RETURNING * INTO v_row;

  RETURN v_row;
END;

DECLARE
  v_user_id uuid := auth.uid();
  v_existing_tenant_id uuid;
  v_tenant_id uuid;
  v_sede_id uuid;
  v_role_owner_id uuid;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF COALESCE(trim(p_tenant_name), '') = '' THEN
    RAISE EXCEPTION 'tenant_name is required';
  END IF;

  IF p_tax_id IS NULL OR p_tax_id !~ '^[0-9]{11}$' THEN
    RAISE EXCEPTION 'tax_id must be an 11-digit RUC';
  END IF;

  IF p_billing_day IS NULL OR p_billing_day < 1 OR p_billing_day > 28 THEN
    RAISE EXCEPTION 'billing_day must be between 1 and 28';
  END IF;

  -- Idempotencia: si el usuario ya tiene tenant, se retorna el existente.
  SELECT p.tenant_id
    INTO v_existing_tenant_id
  FROM public.profiles p
  WHERE p.id = v_user_id
  LIMIT 1;

  IF v_existing_tenant_id IS NOT NULL THEN
    RETURN v_existing_tenant_id;
  END IF;

  -- 1) Crear tenant primero.
  INSERT INTO public.tenants(name, tax_id, industry_type_id, plan_id, status_financial_id, billing_day, max_licenses)
  VALUES (p_tenant_name, p_tax_id, p_industry_type_id, p_plan_id, 'FIN-ACTIVE', p_billing_day, 1)
  RETURNING id INTO v_tenant_id;

  -- 2) Upsert profile con tenant_id ya resuelto (evita auditoría con tenant null).
  INSERT INTO public.profiles(id, tenant_id, full_name)
  VALUES (v_user_id, v_tenant_id, NULL)
  ON CONFLICT (id) DO UPDATE
    SET tenant_id = excluded.tenant_id;

  -- 3) Crear sede principal.
  INSERT INTO public.sedes(tenant_id, name, is_active)
  VALUES (v_tenant_id, 'Principal', true)
  RETURNING id INTO v_sede_id;

  -- 4) Crear rol Owner.
  INSERT INTO public.roles(tenant_id, name, hierarchy_level, is_system_role)
  VALUES (v_tenant_id, 'Owner', 0, true)
  RETURNING id INTO v_role_owner_id;

  -- 5) Asignar permisos al Owner (no-op si cat_permissions aún no está poblada).
  INSERT INTO public.role_permissions(role_id, permission)
  SELECT v_role_owner_id, p.id
  FROM public.cat_permissions p
  ON CONFLICT DO NOTHING;

  -- 6) Asignar Owner al creador.
  INSERT INTO public.user_roles_sedes(tenant_id, user_id, role_id, sede_id)
  VALUES (v_tenant_id, v_user_id, v_role_owner_id, v_sede_id)
  ON CONFLICT DO NOTHING;

  -- 7) Crear/actualizar contrato — [AUDIT-GAP] requiere public.subscription_contracts (fuera de alcance).
  INSERT INTO public.subscription_contracts(
    tenant_id, current_plan_id, status_id, billing_day, grace_days
  )
  VALUES (v_tenant_id, p_plan_id, 'ACTIVE', p_billing_day, 7)
  ON CONFLICT (tenant_id) DO UPDATE
    SET current_plan_id = excluded.current_plan_id,
        status_id = excluded.status_id,
        billing_day = excluded.billing_day,
        updated_at = now();

  -- 8) Crear/actualizar entitlements — [AUDIT-GAP] requiere public.entitlements y
  --    public.plan_policies (fuera de alcance).
  INSERT INTO public.entitlements(tenant_id, plan_id, max_sedes, max_licenses, can_use_terminals)
  SELECT v_tenant_id, pp.plan_id, pp.max_sedes, pp.max_licenses, pp.can_use_terminals
  FROM public.plan_policies pp
  WHERE pp.plan_id = p_plan_id
  ON CONFLICT (tenant_id) DO UPDATE
    SET plan_id = excluded.plan_id,
        max_sedes = excluded.max_sedes,
        max_licenses = excluded.max_licenses,
        can_use_terminals = excluded.can_use_terminals,
        updated_at = now();

  RETURN v_tenant_id;
END;

DECLARE
  v_row      public.codes;
  v_usage_id UUID;
  v_new_status TEXT;
BEGIN
  -- Lock the row to prevent double-spending under concurrent requests
  SELECT * INTO v_row
  FROM public.codes
  WHERE code    = upper(trim(p_code))
    AND status  = 'active'
    AND (expires_at IS NULL OR expires_at > now())
    AND (p_type_id   IS NULL OR type_id   = p_type_id)
    AND (p_tenant_id IS NULL OR tenant_id = p_tenant_id)
  LIMIT 1
  FOR UPDATE;

  IF v_row.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Código inválido, expirado o inactivo');
  END IF;

  IF v_row.max_uses IS NOT NULL AND v_row.current_uses >= v_row.max_uses THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Límite de usos alcanzado');
  END IF;

  -- Determinar nuevo estado
  v_new_status := CASE
    WHEN v_row.max_uses IS NOT NULL AND (v_row.current_uses + 1) >= v_row.max_uses
      THEN 'used'
    ELSE 'active'
  END;

  -- Incrementar uso y actualizar estado si corresponde
  UPDATE public.codes
     SET current_uses = current_uses + 1,
         status       = v_new_status
   WHERE id = v_row.id;

  -- Registrar auditoría
  INSERT INTO public.code_usages (
    code_id, tenant_id, used_by, module_name, observations, ip_address, metadata
  )
  VALUES (
    v_row.id, v_row.tenant_id, auth.uid(),
    p_module_name, p_observations, p_ip_address, p_metadata
  )
  RETURNING id INTO v_usage_id;

  RETURN jsonb_build_object(
    'ok',        true,
    'code_id',   v_row.id,
    'usage_id',  v_usage_id,
    'tenant_id', v_row.tenant_id,
    'type_id',   v_row.type_id,
    'metadata',  v_row.metadata,
    'new_status', v_new_status
  );
END;

DECLARE
  v_code TEXT;
  v_id   UUID;
  v_base TEXT;
  v_tries INT := 0;
BEGIN
  IF p_code IS NULL THEN
    -- Auto-generar: formato ABC-12D3-XY (3-4-2, alfanumérico mayúsculas)
    LOOP
      v_code :=
        upper(substr(md5(random()::text), 1, 3)) || '-' ||
        upper(substr(md5(random()::text || clock_timestamp()::text), 1, 4)) || '-' ||
        upper(substr(md5(clock_timestamp()::text), 1, 2));

      EXIT WHEN NOT EXISTS (
        SELECT 1 FROM public.codes WHERE code = v_code AND tenant_id = p_tenant_id
      ) OR v_tries >= 20;
      v_tries := v_tries + 1;
    END LOOP;
  ELSE
    v_code := upper(trim(p_code));
  END IF;

  INSERT INTO public.codes (
    tenant_id, code, type_id, description,
    max_uses, expires_at, metadata, created_by
  )
  VALUES (
    p_tenant_id, v_code, p_type_id, p_description,
    p_max_uses, p_expires_at, p_metadata, auth.uid()
  )
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('ok', true, 'id', v_id, 'code', v_code);

EXCEPTION WHEN unique_violation THEN
  RETURN jsonb_build_object('ok', false, 'error', 'El código ya existe para este tenant');
END;

declare
  v_link          record;
  v_user_id       uuid    := auth.uid();
  v_membership_id uuid;
  v_entity_id     uuid;
  v_nombre        text;
  v_apellido      text;
  v_num_doc       text;
  v_email         text;
  v_context_type  text;
  v_context_id    uuid;
begin
  if v_user_id is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;

  select * into v_link
  from public.access_links
  where code = p_access_code
    and is_active = true
  for update;

  if not found then
    raise exception 'Código de acceso no válido o inactivo'
      using errcode = 'P0001';
  end if;

  if v_link.expires_at is not null and v_link.expires_at < now() then
    update public.access_links set is_active = false where id = v_link.id;
    raise exception 'El código de acceso ha expirado'
      using errcode = 'P0001';
  end if;

  if v_link.used_count >= v_link.max_uses then
    update public.access_links set is_active = false where id = v_link.id;
    raise exception 'El código de acceso ha alcanzado su límite de usos'
      using errcode = 'P0001';
  end if;

  insert into public.profiles (
    id, tenant_id, full_name, tipo_documento, numero_documento
  ) values (
    v_user_id,
    v_link.tenant_id,
    nullif(trim(coalesce(p_metadata->>'full_name', '')), ''),
    nullif(trim(coalesce(p_metadata->>'tipo_documento', '')), ''),
    nullif(trim(coalesce(p_metadata->>'numero_documento', '')), '')
  )
  on conflict (id) do update
    set tenant_id        = excluded.tenant_id,
        full_name        = coalesce(excluded.full_name,        public.profiles.full_name),
        tipo_documento   = coalesce(excluded.tipo_documento,   public.profiles.tipo_documento),
        numero_documento = coalesce(excluded.numero_documento, public.profiles.numero_documento),
        updated_at       = now();

  -- Traducción target_type (access_links, inglés) → context_type (memberships, español).
  -- GLOBAL no tiene equivalente puntual: se preserva tal cual (ahora permitido por el CHECK ampliado).
  v_context_type := case v_link.target_type
    when 'PROJECT'  then 'PROYECTO'
    when 'PROGRAM'  then 'PROGRAMA'
    when 'ACTIVITY' then 'ACTIVIDAD'
    when 'SEDE'     then 'SEDE'
    else 'GLOBAL'
  end;

  -- context_id es NOT NULL; GLOBAL no tiene target_id puntual, se usa el
  -- propio tenant_id como identificador estable del contexto "global".
  v_context_id := coalesce(v_link.target_id, v_link.tenant_id);

  insert into public.memberships (
    tenant_id, user_id, context_type, context_id, role_id, status
  ) values (
    v_link.tenant_id, v_user_id,
    v_context_type, v_context_id,
    v_link.assigned_role_id, 'active'
  )
  on conflict (tenant_id, user_id, context_type, context_id) do update
    set status     = 'active',
        role_id    = excluded.role_id,
        updated_at = now()
  returning id into v_membership_id;

  if v_link.assigned_role_id is not null and v_link.assigned_sede_id is not null then
    insert into public.user_roles_sedes (
      tenant_id, user_id, role_id, sede_id
    ) values (
      v_link.tenant_id, v_user_id,
      v_link.assigned_role_id, v_link.assigned_sede_id
    )
    on conflict do nothing;
  end if;

  v_nombre := nullif(trim(coalesce(
    p_metadata->>'nombre',
    split_part(coalesce(p_metadata->>'full_name', ''), ' ', 1)
  )), '');

  v_apellido := nullif(trim(coalesce(
    p_metadata->>'apellido',
    case
      when strpos(coalesce(p_metadata->>'full_name', ''), ' ') > 0
      then substring(
             coalesce(p_metadata->>'full_name', '')
             from strpos(coalesce(p_metadata->>'full_name', ''), ' ') + 1
           )
      else null
    end
  )), '');

  v_num_doc := nullif(trim(coalesce(p_metadata->>'numero_documento', '')), '');

  v_email := coalesce(
    nullif(trim(coalesce(p_metadata->>'email', '')), ''),
    (select au.email from auth.users au where au.id = v_user_id)
  );

  if v_link.type = 'VOLUNTEER_JOIN' then
    select id into v_entity_id
    from ong.voluntarios
    where tenant_id = v_link.tenant_id
      and iam_user_id = v_user_id
    limit 1;

    if v_entity_id is null then
      insert into ong.voluntarios (
        tenant_id, iam_user_id,
        nombre, apellido, numero_documento,
        codigo_estado, email
      ) values (
        v_link.tenant_id, v_user_id,
        coalesce(v_nombre,   'Sin nombre'),
        coalesce(v_apellido, 'Sin apellido'),
        coalesce(v_num_doc,  'PENDIENTE'),
        'en_proceso',
        v_email
      )
      returning id into v_entity_id;
    end if;

  elsif v_link.type = 'STAFF_JOIN' then
    insert into rrhh.solicitudes_admision (
      tenant_id, nombres, apellidos, email, estado, fecha_solicitud
    ) values (
      v_link.tenant_id,
      coalesce(v_nombre,   'Sin nombre'),
      coalesce(v_apellido, 'Sin apellido'),
      coalesce(v_email,    'sin-email@pendiente.local'),
      'nueva',
      now()
    )
    returning id into v_entity_id;

  end if;

  update public.access_links
  set used_count = used_count + 1,
      is_active  = case when (used_count + 1) >= max_uses then false else true end
  where id = v_link.id;

  insert into public.audit_logs (
    tenant_id, actor_id, event_type, resource_name,
    payload_after, criticality, retention_until
  ) values (
    v_link.tenant_id, v_user_id,
    'ONBOARDING_COMPLETED', 'access_links',
    jsonb_build_object(
      'link_id',       v_link.id,
      'link_code',     v_link.code,
      'link_type',     v_link.type,
      'membership_id', v_membership_id,
      'entity_id',     v_entity_id
    ),
    'medium',
    now() + make_interval(days => coalesce(
      (select pp.retention_days
       from public.tenants t
       join public.plan_policies pp on pp.plan_id = t.plan_id
       where t.id = v_link.tenant_id
       limit 1),
      180
    ))
  );

  return jsonb_build_object(
    'success',       true,
    'membership_id', v_membership_id,
    'entity_id',     v_entity_id,
    'tenant_id',     v_link.tenant_id,
    'link_type',     v_link.type
  );

exception
  when others then
    raise exception '%', sqlerrm using errcode = sqlstate;
end;

declare
  v_link record;
begin
  select id, type, target_type, expires_at, is_active,
         max_uses, used_count, onboarding_flow
  into   v_link
  from   public.access_links
  where  code = p_code
  limit  1;

  if not found then
    return jsonb_build_object('valid', false, 'reason', 'not_found');
  end if;

  if not v_link.is_active then
    return jsonb_build_object('valid', false, 'reason', 'inactive');
  end if;

  if v_link.expires_at is not null and v_link.expires_at < now() then
    return jsonb_build_object('valid', false, 'reason', 'expired');
  end if;

  if v_link.used_count >= v_link.max_uses then
    return jsonb_build_object('valid', false, 'reason', 'limit_reached');
  end if;

  return jsonb_build_object(
    'valid',           true,
    'type',            v_link.type,
    'target_type',     v_link.target_type,
    'onboarding_flow', v_link.onboarding_flow,
    'expires_at',      v_link.expires_at
  );
end;

DECLARE
  v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_authenticated');
  END IF;

  -- Actualizar fuente de verdad universal
  UPDATE public.profiles
     SET avatar_url = p_url,
         updated_at = now()
   WHERE id = v_uid;

  -- Sincronizar en gym.usuarios (si el usuario tiene perfil gym)
  UPDATE gym.usuarios
     SET foto_url   = p_url,
         updated_at = now()
   WHERE id_usuario = v_uid;

  RETURN jsonb_build_object('ok', true, 'avatar_url', p_url);
END;

BEGIN
  UPDATE public.codes
     SET status   = 'revoked',
         metadata = metadata || jsonb_build_object(
           'revoked_by',     auth.uid(),
           'revoke_reason',  p_reason,
           'revoked_at',     now()
         )
   WHERE id        = p_code_id
     AND tenant_id = public.fn_current_tenant_id()
     AND status   != 'revoked';

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'Código no encontrado, ya revocado, o no pertenece a tu tenant'
    );
  END IF;

  RETURN jsonb_build_object('ok', true, 'code_id', p_code_id);
END;

DECLARE
  v_nombre        TEXT;
  v_telefono      TEXT;
  v_documento     TEXT;
  v_fecha_nac     DATE;
  v_genero        TEXT;
  v_cargo         TEXT;
  v_foto_url      TEXT;
  v_rol           TEXT;
  v_gym_nombre    TEXT;
  v_gym_ruc       TEXT;
  v_gym_ciudad    TEXT;
  v_gym_pais      TEXT;
  v_gym_direccion TEXT;
  v_gym_telefono  TEXT;
  v_gym_email     TEXT;
  v_gym_plan      TEXT;
  v_id_gimnasio   UUID;
  v_tenant_id     UUID;
  v_codigo        TEXT;
  v_staff_code    TEXT;
  v_code_id       UUID;
  v_role_id       UUID;
  v_gym_tenant    UUID;  -- [017] elevado desde bloque interno — necesario para filtro V1
BEGIN
  -- Extraer metadata
  v_nombre     := COALESCE(NULLIF(TRIM(NEW.raw_user_meta_data->>'nombre'),    ''), split_part(NEW.email, '@', 1));
  v_telefono   := NULLIF(TRIM(NEW.raw_user_meta_data->>'telefono'),  '');
  v_documento  := NULLIF(TRIM(NEW.raw_user_meta_data->>'documento'), '');
  v_genero     := NULLIF(NEW.raw_user_meta_data->>'genero',          '');
  v_cargo      := NULLIF(TRIM(NEW.raw_user_meta_data->>'cargo'),     '');
  v_foto_url   := NULLIF(TRIM(NEW.raw_user_meta_data->>'foto_url'),  '');
  v_rol        := COALESCE(NULLIF(NEW.raw_user_meta_data->>'rol',    ''), 'miembro');
  v_staff_code := NULLIF(UPPER(TRIM(NEW.raw_user_meta_data->>'staff_code')), '');

  BEGIN
    v_fecha_nac := (NEW.raw_user_meta_data->>'fecha_nacimiento')::DATE;
  EXCEPTION WHEN OTHERS THEN v_fecha_nac := NULL; END;

  IF v_genero NOT IN ('M', 'F', 'Otro') THEN v_genero := NULL; END IF;

  -- ── SIEMPRE: perfil universal BD Maestra ─────────────────────────────────
  INSERT INTO public.profiles (id, full_name, tipo_documento, numero_documento, genero)
  VALUES (
    NEW.id, v_nombre,
    CASE WHEN v_documento IS NOT NULL THEN 'DNI' ELSE NULL END,
    v_documento, v_genero
  )
  ON CONFLICT (id) DO UPDATE
    SET full_name        = EXCLUDED.full_name,
        tipo_documento   = COALESCE(EXCLUDED.tipo_documento,   profiles.tipo_documento),
        numero_documento = COALESCE(EXCLUDED.numero_documento, profiles.numero_documento),
        genero           = COALESCE(EXCLUDED.genero,           profiles.genero);

  v_gym_nombre := NULLIF(TRIM(NEW.raw_user_meta_data->>'gym_nombre'), '');

  -- ── CASO A: Onboarding — dueño registra su gimnasio ──────────────────────
  IF v_gym_nombre IS NOT NULL THEN
    v_gym_ruc       := NULLIF(TRIM(NEW.raw_user_meta_data->>'gym_ruc'),       '');
    v_gym_ciudad    := COALESCE(NULLIF(TRIM(NEW.raw_user_meta_data->>'gym_ciudad'), ''), 'Lima');
    v_gym_pais      := COALESCE(NULLIF(TRIM(NEW.raw_user_meta_data->>'gym_pais'),   ''), 'Perú');
    v_gym_direccion := NULLIF(TRIM(NEW.raw_user_meta_data->>'gym_direccion'),  '');
    v_gym_telefono  := NULLIF(TRIM(NEW.raw_user_meta_data->>'gym_telefono'),   '');
    v_gym_email     := NULLIF(TRIM(NEW.raw_user_meta_data->>'gym_email'),      '');
    v_gym_plan      := COALESCE(NULLIF(NEW.raw_user_meta_data->>'gym_plan',    ''), 'mediano');

    -- 1. Registrar como organización en BD Maestra
    INSERT INTO public.tenants (
      name, tax_id, industry_type_id, plan_id, status_financial_id, max_licenses
    )
    VALUES (
      v_gym_nombre,
      COALESCE(v_gym_ruc, 'PENDIENTE-' || gen_random_uuid()::text),
      'gym',
      public._gym_plan_to_bd(v_gym_plan),
      'FIN-PENDING',
      public._gym_plan_to_licenses(v_gym_plan)
    )
    RETURNING id INTO v_tenant_id;

    -- [018] Sembrar los 7 roles de sistema del nuevo tenant gym
    PERFORM public.seed_gym_roles(v_tenant_id);

    -- 2. Crear gym
    v_codigo := public.generate_gym_code(v_gym_nombre);
    INSERT INTO gym.gimnasios (
      nombre, ruc, ciudad, pais, direccion, telefono, email,
      plan_suscripcion, estado, tenant_id
    )
    VALUES (
      v_gym_nombre, v_gym_ruc, v_gym_ciudad, v_gym_pais, v_gym_direccion,
      v_gym_telefono, v_gym_email, v_gym_plan, 'activo', v_tenant_id
    )
    RETURNING id_gimnasio INTO v_id_gimnasio;

    -- 3. Código de acceso (miembros)
    INSERT INTO gym.codigos_acceso (id_gimnasio, codigo, tipo, descripcion)
    VALUES (v_id_gimnasio, v_codigo, 'general', 'Codigo principal del gimnasio');

    -- 4. Perfil gym del dueño
    INSERT INTO gym.usuarios (
      id_usuario, email, nombre, telefono, documento, fecha_nacimiento,
      genero, foto_url, cargo, id_gimnasio, rol, estado
    )
    VALUES (
      NEW.id, NEW.email, v_nombre, v_telefono, v_documento, v_fecha_nac,
      v_genero, v_foto_url, COALESCE(v_cargo, 'Gerente General'),
      v_id_gimnasio, 'gerente', 'activo'
    )
    ON CONFLICT (id_usuario) DO NOTHING;

    -- 5. Vincular profile al tenant
    UPDATE public.profiles SET tenant_id = v_tenant_id WHERE id = NEW.id;

    -- 6. Asignar rol 'Administrador General' al dueño
    SELECT id INTO v_role_id
    FROM public.roles
    WHERE tenant_id = v_tenant_id AND name = 'Administrador General';

    IF v_role_id IS NOT NULL THEN
      INSERT INTO public.user_roles (tenant_id, user_id, role_id)
      VALUES (v_tenant_id, NEW.id, v_role_id)
      ON CONFLICT DO NOTHING;
    END IF;

  -- ── CASO B: Signup con código (miembro o staff) ───────────────────────────
  ELSIF NEW.raw_user_meta_data->>'id_gimnasio' IS NOT NULL THEN
    v_id_gimnasio := (NEW.raw_user_meta_data->>'id_gimnasio')::uuid;

    -- Perfil gym
    INSERT INTO gym.usuarios (
      id_usuario, email, nombre, telefono, documento, fecha_nacimiento,
      genero, foto_url, id_gimnasio, rol, estado
    )
    VALUES (
      NEW.id, NEW.email, v_nombre, v_telefono, v_documento, v_fecha_nac,
      v_genero, v_foto_url, v_id_gimnasio, v_rol, 'activo'
    )
    ON CONFLICT (id_usuario) DO NOTHING;

    -- Vincular al tenant
    UPDATE public.profiles p
       SET tenant_id = g.tenant_id
      FROM gym.gimnasios g
     WHERE g.id_gimnasio = v_id_gimnasio
       AND p.id = NEW.id
       AND g.tenant_id IS NOT NULL;

    -- Si hay staff_code → asignar rol del code_grants
    IF v_staff_code IS NOT NULL THEN

      -- [017] V1: resolver tenant del gym ANTES del SELECT del código
      SELECT g.tenant_id INTO v_gym_tenant
      FROM gym.gimnasios g WHERE g.id_gimnasio = v_id_gimnasio;

      -- [017] V1 + V3 + V4: SELECT con aislamiento tenant, tipo restringido y lock de fila
      SELECT c.id, cg.role_id
      INTO   v_code_id, v_role_id
      FROM   public.codes c
      JOIN   public.code_grants cg ON cg.code_id = c.id
      WHERE  c.code      = v_staff_code
        AND  c.status    = 'active'
        AND  c.tenant_id = v_gym_tenant
        AND  c.type_id   = 'USER_INVITE'
        AND  (c.expires_at IS NULL OR c.expires_at > now())
        AND  (c.max_uses IS NULL OR c.current_uses < c.max_uses)
      LIMIT  1
      FOR UPDATE OF c;

      IF v_code_id IS NOT NULL THEN
        INSERT INTO public.user_roles (tenant_id, user_id, role_id)
        VALUES (v_gym_tenant, NEW.id, v_role_id)
        ON CONFLICT DO NOTHING;

        -- Consumir el código
        UPDATE public.codes
           SET current_uses = current_uses + 1,
               status = CASE
                 WHEN max_uses IS NOT NULL AND (current_uses + 1) >= max_uses THEN 'used'
                 ELSE 'active'
               END
         WHERE id = v_code_id;

        -- Registrar uso
        INSERT INTO public.code_usages (code_id, tenant_id, used_by, module_name)
        VALUES (v_code_id, v_gym_tenant, NEW.id, 'gym');
      END IF;

    ELSE
      -- Sin staff_code → asignar rol 'Miembro' por defecto
      SELECT g.tenant_id INTO v_tenant_id
      FROM gym.gimnasios g WHERE g.id_gimnasio = v_id_gimnasio;

      IF v_tenant_id IS NOT NULL THEN
        SELECT id INTO v_role_id
        FROM public.roles
        WHERE tenant_id = v_tenant_id AND name = 'Miembro';

        IF v_role_id IS NOT NULL THEN
          INSERT INTO public.user_roles (tenant_id, user_id, role_id)
          VALUES (v_tenant_id, NEW.id, v_role_id)
          ON CONFLICT DO NOTHING;
        END IF;
      END IF;
    END IF;

  -- ── CASO C: Otro sistema ──────────────────────────────────────────────────
  END IF;

  RETURN NEW;

EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'handle_new_user FALLÓ para % (%) — Error: % [%]',
    NEW.email, NEW.id, SQLERRM, SQLSTATE;
  RETURN NEW;
END;

DECLARE
  v_result  JSONB;
  v_code_id UUID;
  v_code    TEXT;
  v_allowed BOOLEAN;
BEGIN
  -- [019c] Validar el permiso contra el stack GYM (user_roles), que es donde el
  --        onboarding gym asigna roles. Consulta directa → evita la ambigüedad de
  --        overload de fn_has_permission y apunta a la tabla correcta para este flujo.
  SELECT EXISTS (
    SELECT 1
    FROM public.user_roles ur
    JOIN public.roles r             ON r.id = ur.role_id
    JOIN public.role_permissions rp ON rp.role_id = r.id
    WHERE ur.user_id   = auth.uid()
      AND ur.tenant_id = p_tenant_id
      AND rp.permission = 'gym.codigos.crear'
      AND (ur.expires_at IS NULL OR ur.expires_at > now())
  ) INTO v_allowed;

  IF NOT v_allowed THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sin permiso: gym.codigos.crear requerido');
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.roles WHERE id = p_role_id AND tenant_id = p_tenant_id
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'El rol no pertenece a este tenant');
  END IF;

  SELECT public.fn_create_code(
    p_tenant_id   => p_tenant_id,
    p_type_id     => 'USER_INVITE',
    p_code        => p_custom_code,
    p_description => COALESCE(p_description, 'Código de staff'),
    p_max_uses    => p_max_uses,
    p_expires_at  => p_expires_at,
    p_metadata    => jsonb_build_object('role_id', p_role_id)
  ) INTO v_result;

  IF NOT (v_result->>'ok')::boolean THEN
    RETURN v_result;
  END IF;

  v_code_id := (v_result->>'id')::uuid;
  v_code    := v_result->>'code';

  INSERT INTO public.code_grants (code_id, role_id)
  VALUES (v_code_id, p_role_id);

  RETURN jsonb_build_object(
    'ok', true, 'code_id', v_code_id, 'code', v_code,
    'role_id', p_role_id, 'max_uses', p_max_uses, 'expires_at', p_expires_at
  );
END;

