DECLARE
  v_raw_token text;
  v_token_hash text;
  v_prefix text;
BEGIN
  -- Generate 32 bytes of secure random hex + democra prefix
  v_raw_token := 'dmc_' || encode(gen_random_bytes(24), 'hex');
  v_prefix := substring(v_raw_token from 1 for 8);
  v_token_hash := crypt(v_raw_token, gen_salt('bf'));

  INSERT INTO public.api_tokens (user_id, tenant_id, name, token_hash, prefix)
  VALUES (auth.uid(), p_tenant_id, p_name, v_token_hash, v_prefix);

  RETURN v_raw_token;
END;

BEGIN
  DELETE FROM public.api_tokens 
  WHERE id = p_token_id AND user_id = auth.uid();
END;

DECLARE
  v_tenant_id  UUID;
  v_role_name  TEXT;
  v_role_id    UUID;
  -- Conjunto de nombres de rol de sistema "mapeables" desde el gimnasio.
  -- Se usa para acotar el borrado del rol anterior SIN tocar roles de otros
  -- módulos (p.ej. ONG) ni asignaciones manuales.
  v_gym_role_names TEXT[] := ARRAY[
    'Administrador General','Supervisor','Cajero',
    'Recepcionista','Entrenador','Nutricionista','Miembro'
  ];
BEGIN
  -- Lógica protegida: cualquier error se captura abajo y NO propaga al INSERT/UPDATE.
  BEGIN

    -- 1.a Derivar el tenant_id del gimnasio del usuario (gym.usuarios no lo almacena).
    SELECT g.tenant_id
      INTO v_tenant_id
      FROM gym.gimnasios g
     WHERE g.id_gimnasio = NEW.id_gimnasio;

    -- 1.b Mapear el enum de texto rol → nombre canónico en public.roles.
    v_role_name := CASE lower(COALESCE(NEW.rol, ''))
      WHEN 'admin'         THEN 'Administrador General'
      WHEN 'gerente'       THEN 'Administrador General'  -- dueño/gerente = admin del tenant gym
      WHEN 'recepcionista' THEN 'Recepcionista'
      WHEN 'entrenador'    THEN 'Entrenador'
      WHEN 'nutricionista' THEN 'Nutricionista'
      WHEN 'miembro'       THEN 'Miembro'
      WHEN 'cliente'       THEN 'Miembro'                -- cliente se trata como miembro
      ELSE NULL                                          -- sin equivalente RBAC (p.ej. rol nuevo)
    END;

    -- 1.c Guardas de resiliencia: sin tenant o sin mapeo → advertir y salir sin bloquear.
    IF v_tenant_id IS NULL THEN
      PERFORM gym._log_sync_warning(
        NULL, NEW.id_usuario, NEW.rol,
        'tenant_id NULL: gimnasio ' || COALESCE(NEW.id_gimnasio::text,'(null)') ||
        ' sin tenant vinculado; no se sincroniza RBAC.'
      );
      RETURN NEW;
    END IF;

    IF v_role_name IS NULL THEN
      PERFORM gym._log_sync_warning(
        v_tenant_id, NEW.id_usuario, NEW.rol,
        'rol sin equivalente en catálogo maestro; no se sincroniza RBAC.'
      );
      RETURN NEW;
    END IF;

    -- 1.d Resolver el role_id en el catálogo maestro para ese tenant.
    SELECT r.id
      INTO v_role_id
      FROM public.roles r
     WHERE r.tenant_id = v_tenant_id
       AND r.name      = v_role_name
     LIMIT 1;

    IF v_role_id IS NULL THEN
      PERFORM gym._log_sync_warning(
        v_tenant_id, NEW.id_usuario, NEW.rol,
        'rol "' || v_role_name || '" no existe en public.roles para el tenant; ' ||
        'ejecutar seed de roles (migración 016) antes de sincronizar.'
      );
      RETURN NEW;
    END IF;

    -- 1.e Si el rol cambió: retirar asignaciones previas de roles-gimnasio distintas
    --     a la nueva (acotado a v_gym_role_names para no borrar roles de otros módulos).
    DELETE FROM public.user_roles ur
     WHERE ur.tenant_id = v_tenant_id
       AND ur.user_id   = NEW.id_usuario
       AND ur.role_id  <> v_role_id
       AND ur.role_id IN (
             SELECT r.id FROM public.roles r
              WHERE r.tenant_id = v_tenant_id
                AND r.name = ANY(v_gym_role_names)
           );

    -- 1.f Garantizar la asignación equivalente (idempotente).
    INSERT INTO public.user_roles (tenant_id, user_id, role_id, assigned_by, assigned_at)
    VALUES (v_tenant_id, NEW.id_usuario, v_role_id, NULL, now())
    ON CONFLICT (tenant_id, user_id, role_id) DO NOTHING;

    RETURN NEW;

  EXCEPTION
    WHEN OTHERS THEN
      -- Resiliencia total: registrar y continuar. El write del gimnasio no se revierte.
      PERFORM gym._log_sync_warning(
        v_tenant_id, NEW.id_usuario, NEW.rol,
        'Excepción en sync RBAC: ' || SQLERRM
      );
      RETURN NEW;
  END;
END;

DECLARE
  v_user_id   UUID := auth.uid();
  v_gym_id    UUID;
  v_code_id   UUID;
  v_max_usos  INT;
  v_usos_act  INT;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;

  -- Buscar el código activo
  SELECT id_codigo, id_gimnasio, usos_max, usos_actuales
    INTO v_code_id, v_gym_id, v_max_usos, v_usos_act
    FROM gym.codigos_acceso
   WHERE codigo = upper(trim(p_codigo))
     AND activo = TRUE
     AND (fecha_expiracion IS NULL OR fecha_expiracion > NOW())
   LIMIT 1;

  IF v_code_id IS NULL THEN
    RAISE EXCEPTION 'Código inválido, inactivo o expirado';
  END IF;

  -- Verificar límite de usos
  IF v_max_usos IS NOT NULL AND v_usos_act >= v_max_usos THEN
    RAISE EXCEPTION 'El código ya alcanzó su límite de usos';
  END IF;

  -- Asignar gym al perfil del usuario (si aún no tiene uno)
  UPDATE gym.usuarios
     SET id_gimnasio = v_gym_id,
         nombre      = COALESCE(NULLIF(p_nombre, ''), nombre),
         cargo       = COALESCE(NULLIF(p_cargo, ''), cargo),
         estado      = 'activo'
   WHERE id_usuario = v_user_id
     AND id_gimnasio IS NULL;

  -- Si no tenía perfil, crearlo
  IF NOT FOUND THEN
    INSERT INTO gym.usuarios (id_usuario, email, nombre, cargo, id_gimnasio, rol, estado)
    SELECT
      v_user_id,
      au.email,
      COALESCE(NULLIF(p_nombre, ''), NULLIF(au.raw_user_meta_data->>'nombre', ''), split_part(au.email, '@', 1)),
      p_cargo,
      v_gym_id,
      'miembro',
      'activo'
    FROM auth.users au WHERE au.id = v_user_id
    ON CONFLICT (id_usuario) DO UPDATE
      SET id_gimnasio = v_gym_id, estado = 'activo';
  END IF;

  -- Incrementar contador de usos del código
  UPDATE gym.codigos_acceso
     SET usos_actuales = usos_actuales + 1
   WHERE id_codigo = v_code_id;

  RETURN jsonb_build_object(
    'ok',          true,
    'id_gimnasio', v_gym_id,
    'codigo',      p_codigo
  );

EXCEPTION WHEN OTHERS THEN
  RAISE EXCEPTION 'join_gym_with_code: %', SQLERRM;
END;

DECLARE
    v_tenant_id UUID;
    v_usuario_id UUID := NULL;
    v_registro_id UUID;
BEGIN
    -- Capturar el tenant_id de la tabla origen
    IF (TG_OP = 'DELETE') THEN
        v_tenant_id := OLD.tenant_id;
        v_registro_id := (OLD.*).id; -- Asumimos genéricamente
    ELSE
        v_tenant_id := NEW.tenant_id;
    END IF;

    -- Intentar extraer el ID de la primera columna (Primary Key)
    EXECUTE format('SELECT ($1).%I', TG_ARGV[0]) INTO v_registro_id USING NEW;

    -- Intentar capturar el actor de la acción (si la tabla lo permite)
    BEGIN
        EXECUTE 'SELECT ($1).usuario_id' INTO v_usuario_id USING NEW;
    EXCEPTION WHEN undefined_column THEN
        BEGIN
            EXECUTE 'SELECT ($1).estudiante_id' INTO v_usuario_id USING NEW;
        EXCEPTION WHEN undefined_column THEN
            v_usuario_id := NULL;
        END;
    END;

    -- Insertar el registro de telemetría de forma asíncrona y segura
    INSERT INTO telemetria.estadisticas_uso (
        tenant_id, 
        tabla_origen, 
        operacion, 
        registro_id, 
        usuario_id, 
        payload_json
    ) VALUES (
        v_tenant_id,
        TG_TABLE_SCHEMA || '.' || TG_TABLE_NAME,
        TG_OP,
        v_registro_id,
        v_usuario_id,
        row_to_json(NEW)::JSONB
    );

    RETURN NEW;
END;

DECLARE
    v_user_id UUID := COALESCE(p_user_id, auth.uid());
    v_existing_tenant_id UUID;
    v_tenant_id UUID := gen_random_uuid();
    v_sede_id UUID := gen_random_uuid();
    v_role_owner_id UUID := gen_random_uuid();
    v_max_licenses INT := 5;
    v_max_sedes INT := 1;
    v_can_use_terminals BOOLEAN := false;
    v_result JSONB;
BEGIN
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Usuario no autenticado' USING ERRCODE = 'INVALID_AUTHORIZATION_SPECULATION';
    END IF;

    IF p_razon_social IS NULL OR trim(p_razon_social) = '' THEN
        RAISE EXCEPTION 'La razon social (p_razon_social) es requerida' USING ERRCODE = 'INVALID_PARAMETER_VALUE';
    END IF;

    IF p_tax_id IS NULL OR p_tax_id !~ '^[0-9]{11}$' THEN
        RAISE EXCEPTION 'El tax_id (RUC) % debe constar de 11 digitos numericos', p_tax_id USING ERRCODE = 'INVALID_PARAMETER_VALUE';
    END IF;

    -- Idempotencia: si el usuario ya posee un tenant_id asignado, lo retorna sin duplicar
    SELECT p.tenant_id INTO v_existing_tenant_id
    FROM public.profiles p
    WHERE p.id = v_user_id
    LIMIT 1;

    IF v_existing_tenant_id IS NOT NULL THEN
        RETURN jsonb_build_object(
            'success', true,
            'tenant_id', v_existing_tenant_id,
            'user_id', v_user_id,
            'message', 'El usuario ya cuenta con una organizacion asignada.'
        );
    END IF;

    -- 1. Validar unicidad de RUC registrado previamente
    IF EXISTS (SELECT 1 FROM public.tenants WHERE tax_id = p_tax_id) THEN
        RAISE EXCEPTION 'El RUC % ya se encuentra registrado en la plataforma.', p_tax_id
            USING ERRCODE = 'UNIQUE_VIOLATION';
    END IF;

    -- 2. Crear Organizacion (Tenant)
    INSERT INTO public.tenants (
        id, name, trade_name, tax_id, industry_type_id, 
        plan_id, status_financial_id, billing_day, max_licenses, created_at
    ) VALUES (
        v_tenant_id, p_razon_social, p_trade_name, p_tax_id, p_industry_type_id,
        p_plan_id, 'FIN-ACTIVE', LEAST(GREATEST(COALESCE(p_billing_day, 1), 1), 28), v_max_licenses, NOW()
    );

    -- 3. Crear o Actualizar Perfil del Usuario Dueno
    INSERT INTO public.profiles (
        id, tenant_id, full_name, doc_type, doc_number, phone_number,
        avatar_url, email_verified, verify_token_hash, updated_at
    ) VALUES (
        v_user_id, v_tenant_id, p_full_name, p_doc_type, p_doc_number, p_phone_number,
        p_avatar_url, true, p_verify_token_hash, NOW()
    )
    ON CONFLICT (id) DO UPDATE SET
        tenant_id = v_tenant_id,
        full_name = COALESCE(EXCLUDED.full_name, profiles.full_name),
        doc_type = COALESCE(EXCLUDED.doc_type, profiles.doc_type),
        doc_number = COALESCE(EXCLUDED.doc_number, profiles.doc_number),
        phone_number = COALESCE(EXCLUDED.phone_number, profiles.phone_number),
        avatar_url = COALESCE(EXCLUDED.avatar_url, profiles.avatar_url),
        email_verified = true,
        updated_at = NOW();

    -- 4. Crear Sede Matriz 'Principal'
    INSERT INTO public.sedes (
        id, tenant_id, name, address, is_active, created_at
    ) VALUES (
        v_sede_id, v_tenant_id, 'Principal', COALESCE(p_address, 'Sede Matriz Principal'), true, NOW()
    );

    -- 5. Crear Rol Administrador 'Owner' (Jerarquia 0)
    INSERT INTO public.roles (
        id, tenant_id, name, hierarchy_level, is_system_role, created_at
    ) VALUES (
        v_role_owner_id, v_tenant_id, 'Owner', 0, true, NOW()
    );

    -- 6. Copiar Permisos de Catalogo a Rol Owner
    INSERT INTO public.role_permissions (role_id, permission_id)
    SELECT v_role_owner_id, id FROM public.cat_permissions
    ON CONFLICT DO NOTHING;

    -- 7. Asignacion Tripartita (Usuario + Rol Owner + Sede Principal + Tenant)
    INSERT INTO public.user_roles_sedes (
        tenant_id, user_id, role_id, sede_id, created_at
    ) VALUES (
        v_tenant_id, v_user_id, v_role_owner_id, v_sede_id, NOW()
    )
    ON CONFLICT DO NOTHING;

    -- 8. Contrato de Suscripcion Inicial
    INSERT INTO public.subscription_contracts (
        id, tenant_id, current_plan_id, status_id, billing_day, grace_days, created_at
    ) VALUES (
        gen_random_uuid(), v_tenant_id, p_plan_id, 'ACTIVE', COALESCE(p_billing_day, 1), 7, NOW()
    )
    ON CONFLICT (tenant_id) DO UPDATE SET
        current_plan_id = EXCLUDED.current_plan_id,
        updated_at = NOW();

    -- 9. Entitlements y Limite del Plan
    INSERT INTO public.entitlements (
        id, tenant_id, max_sedes, max_licenses, can_use_terminals, created_at
    ) VALUES (
        gen_random_uuid(), v_tenant_id, v_max_sedes, v_max_licenses, v_can_use_terminals, NOW()
    )
    ON CONFLICT (tenant_id) DO UPDATE SET
        max_sedes = EXCLUDED.max_sedes,
        max_licenses = EXCLUDED.max_licenses,
        updated_at = NOW();

    -- 10. Construir respuesta JSON de confirmacion
    v_result := jsonb_build_object(
        'success', true,
        'tenant_id', v_tenant_id,
        'user_id', v_user_id,
        'sede_id', v_sede_id,
        'role_id', v_role_owner_id,
        'message', 'Bootstrapping v2.0 de la organizacion completado exitosamente.'
    );

    RETURN v_result;

EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'Error durante el onboarding del tenant: % (SQLSTATE: %)', SQLERRM, SQLSTATE;
END;
